const groupBy = (arr, key) =>
  arr.reduce((acc, item) => {
    (acc[item[key]] ||= []).push(item);
    return acc;
  }, {});

console.log(groupBy([{t: "a"}, {t: "b"}, {t: "a"}], "t"));
```

Для кожного елемента беремо масив за ключем (створюємо, якщо його ще немає) і додаємо елемент.

Here is a solution:

```javascript
function debounce(fn, delay) {
  let timer;
  return (...args) => {
    clearTimeout(timer);
    timer = setTimeout(() => fn(...args), delay);
  };
}

const onType = debounce((q) => console.log("search", q), 300);
```

Every new call resets the timer, so `fn` runs only after a pause of `delay` ms.
